package cmd

import (
	"strings"

	"github.com/spf13/cobra"
)

// These descriptions supplement original constructors after the canonical
// command tree exists. Each path has its own concept and a usable invocation.
func applyReadHelp(root *cobra.Command) {
	for _, help := range readCommandHelp {
		command := root
		for name := range strings.FieldsSeq(help.path) {
			command = directCommand(command, name)
			if command == nil {
				break
			}
		}
		if command == nil {
			continue
		}
		if help.concept != "" && !strings.Contains(command.Long, help.concept) {
			if command.Long != "" {
				command.Long += "\n\n"
			}
			command.Long += help.concept
		}
		if command.Example == "" && help.example != "" {
			command.Example = "  msgvault " + help.example
		}
	}
}

